package com.mhtextractor.app;

import com.mhtextractor.model.PreviewItem;
import com.mhtextractor.processor.BatchProcessor;
import com.mhtextractor.util.GroupStructure;
import com.mhtextractor.util.IncrementalImport;
import com.mhtextractor.util.SanitizeUtils;

import java.io.File;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/**
 * 导入规则服务（Q2/P1）：把"统一导入"里<b>与界面无关</b>的规则从控制器搬进无头应用层 ——
 * 地址规范化、会话累计状态、一轮计划到"要新建哪些条目/哪些组"的换算、组名计算。
 *
 * <p><b>本类零 JavaFX、零第三方依赖、不调 {@code I18n}</b>（{@code app} 层由 {@code ArchitectureTest} 强制）。
 * 因此它<b>不产出任何用户文案</b>：需要写日志/弹提醒的地方，本类只回传<b>结构化事实</b>
 * （{@link NormalizeResult} / {@link RoundOutcome}），由调用方（B5-1 起 = 同层的
 * {@link WorkspaceImportCoordinator}）用 {@code log.*} 键产出原文案。这样"规则可无头单测"与
 * "日志文案随界面语言走"两件事同时成立。</p>
 *
 * <h2>分层：本类与 {@link WorkspaceImportCoordinator} 的边界</h2>
 * <ul>
 *   <li><b>本类（app）</b>：纯规则与纯数据 —— 规范化、去重口径、条目构造、累计计数、组名计算。
 *       所有方法同步、无线程、不碰任何控件与模型结构。</li>
 *   <li><b>{@link WorkspaceImportCoordinator}（app，B5-1 起）</b>：会话生命周期 —— 后台线程、
 *       宿主派发（生产 = {@code Platform.runLater}）、配额确认往返、模型命令
 *       （{@code WorkspaceModel.appendItems/appendGroup/push}）、刷新事件与唯一收尾。</li>
 * </ul>
 *
 * <h2>为什么会话累计状态（原控制器的 7 个字段）落在这里</h2>
 * <p>原控制器用 7 个字段承载"本次导入的累计"：{@code importAccumulated}、{@code importGroupCount}
 * 与 5 个扫描计数器。它们既不是界面控件，也不是模型结构，只是<b>一轮扫描的会话状态</b>；
 * 放在 {@link Session} 里之后，{@code WorkspaceImportServiceTest} 可以完全不启动界面就验证
 * "累计值是扫描器的累计值"这一语义。</p>
 *
 * <h2>必须保持的既有语义（改动前逐条核对，见 {@code MainController} 原实现）</h2>
 * <ol>
 *   <li><b>去重口径 = 可见项</b>（{@code removed == false}），<b>不是</b>全量项。已移除项仍留在数据序里，
 *       不得视为"已导入"而整批跳过 —— 这是提交 {@code 4dd4852} 修的缺陷（"移除后再也加不回来"），
 *       调用方必须传"可见项路径"，见 {@link IncrementalImport#findNewFiles} 的 javadoc。</li>
 *   <li><b>无新文件 ⇒ 该批次不建组</b>（RISK-1）：{@link ResolvedBatch#skipped()} 为真，调用方只打 debug 日志。</li>
 *   <li><b>组成员只入组、不入顶层</b>：{@code grouped()} 的批次不得再 {@code appendItems}（否则双计）。</li>
 *   <li><b>一轮内去重是增量的</b>：同一轮里前面的批次已产出的条目，对后面的批次同样算"已存在"
 *       （原实现每批都重新读一次当前可见项）。本类用 {@code seen} 集合复现该口径。</li>
 *   <li><b>一次导入 = 一条撤销记录</b>：累计列表每轮都携带全量（最后一次 push 覆盖前几次的效果），
 *       本类只负责累计，压记录在 GUI 层。</li>
 * </ol>
 */
public final class WorkspaceImportService {

    // ==================== 地址规范化 ====================

    /**
     * 一条被丢弃的地址。
     *
     * @param address  被丢弃的原始地址串
     * @param ancestor {@code null} = 与已保留地址完全重复；非 {@code null} = 被该祖先地址覆盖
     */
    public record DroppedAddress(String address, String ancestor) {
    }

    /**
     * 地址规范化结果。
     *
     * <p><b>为什么既要有序的 {@code dropped} 又要两个便利视图</b>：调用方要按<b>输入顺序</b>产出日志
     * （{@code log.maincontroller.06} 重复 / {@code .07} 被祖先覆盖），而这两类事件在原实现里是<b>同一个循环</b>
     * 里交替发出的 —— 例如输入 {@code [A, A的子目录, A]} 的事件顺序是"被祖先覆盖"在前、"重复"在后。
     * 若只回传两个独立的列表，调用方就无法复原这个相对顺序（会变成"所有重复在前"）。
     * 故 {@link #dropped()} 是<b>权威的有序事件序列</b>，两个便利视图只供断言与展示。</p>
     */
    public record NormalizeResult(List<String> kept, List<DroppedAddress> dropped) {

        public NormalizeResult {
            kept = List.copyOf(kept);
            dropped = List.copyOf(dropped);
        }

        /** 完全重复（与已保留地址同串）而被合并掉的地址，按输入顺序 */
        public List<String> duplicates() {
            return dropped.stream().filter(d -> d.ancestor() == null)
                    .map(DroppedAddress::address).toList();
        }

        /** 被祖先地址覆盖而被合并掉的地址（含其祖先），按输入顺序 */
        public List<DroppedAddress> coveredByAncestor() {
            return dropped.stream().filter(d -> d.ancestor() != null).toList();
        }
    }

    /**
     * 地址规范化（RISK-6）：重复地址合并；祖先/后代包含关系合并为祖先（丢弃后代）。
     *
     * <p>与原实现逐字等价的规则：</p>
     * <ul>
     *   <li>{@code null} / 空串 / 全空白 → 忽略（<b>不计入</b> {@code dropped}，原实现也没有日志）；</li>
     *   <li>与已保留地址同串 → 丢入 {@code dropped(ancestor = null)}；</li>
     *   <li>是某个已保留地址的后代 → 丢入 {@code dropped(ancestor = 该祖先)}；</li>
     *   <li>反过来（祖先出现在后代<b>之后</b>）→ 悄悄移除先前保留的后代 —— 原实现这里<b>没有日志</b>，
     *       本类同样不记事件（<b>不得</b>为它补一条日志，那会引入用户可见的新日志行）；</li>
     *   <li>无效路径格式（{@code Path.of} 抛 {@code InvalidPathException}）→ <b>原样保留</b>，
     *       由扫描器按"不可读"计数。</li>
     * </ul>
     */
    public NormalizeResult normalizeAddresses(List<String> addresses) {
        List<String> kept = new ArrayList<>();
        List<DroppedAddress> dropped = new ArrayList<>();
        if (addresses == null) {
            return new NormalizeResult(kept, dropped);
        }
        for (String a : addresses) {
            if (a == null || a.isBlank()) {
                continue;
            }
            if (kept.stream().anyMatch(a::equals)) {
                dropped.add(new DroppedAddress(a, null));
                continue;
            }
            String ancestor = kept.stream().filter(k -> isDescendantOf(a, k)).findFirst().orElse(null);
            if (ancestor != null) {
                dropped.add(new DroppedAddress(a, ancestor));
                continue;
            }
            kept.removeIf(k -> isDescendantOf(k, a));
            kept.add(a);
        }
        return new NormalizeResult(kept, dropped);
    }

    /** 路径包含判定（纯函数，无副作用）：{@code child} 是 {@code ancestor} 的后代且不等于它 */
    public static boolean isDescendantOf(String child, String ancestor) {
        try {
            Path cp = Path.of(child);
            Path ap = Path.of(ancestor);
            return !cp.equals(ap) && cp.startsWith(ap);
        } catch (RuntimeException e) {
            return false;
        }
    }

    // ==================== 会话 ====================

    /**
     * 导入会话：扫描器（每一轮从断点续扫）+ 本次导入的累计状态。
     *
     * <p><b>不持有任何线程与界面对象</b>：线程与派发在 {@link WorkspaceImportCoordinator}。
     * 扫描器只能被创建它的线程使用（见 {@link MhtImportPlanner#scanner}），故本对象跨线程时
     * 只有"累计字段"被两方读写 —— 与迁移前控制器字段的形态一致（写方是 GUI 线程，读方是导入后台线程
     * 构造配额文案与收尾汇总）。</p>
     */
    public static final class Session {

        private final List<String> addresses;
        private final String sourceDesc;
        private final boolean fromDrag;
        private final MhtImportPlanner.Scanner scanner;

        /** 本次导入累计新增的条目（收尾统一预解析，避免 O(n²)） */
        private final List<PreviewItem> accumulated = new ArrayList<>();
        /** 本次导入累计自动创建的组数（配额确认框/收尾汇总用） */
        private int groupCount;
        /** 扫描计数器：Plan 里给的是扫描器累计值，每轮原样同步（即使本轮无批次） */
        private int ignoredNonMht;
        private int hiddenDirs;
        private int emptyDirs;
        private int unreadable;
        private int depthLimited;

        private Session(List<String> addresses, String sourceDesc, boolean fromDrag,
                        MhtImportPlanner.Scanner scanner) {
            this.addresses = addresses;
            this.sourceDesc = sourceDesc;
            this.fromDrag = fromDrag;
            this.scanner = scanner;
        }

        public List<String> addresses() {
            return addresses;
        }

        public String sourceDesc() {
            return sourceDesc;
        }

        public boolean fromDrag() {
            return fromDrag;
        }

        /** 本次导入累计新增的条目（只读快照） */
        public List<PreviewItem> accumulated() {
            return List.copyOf(accumulated);
        }

        public int groupCount() {
            return groupCount;
        }

        public int ignoredNonMht() {
            return ignoredNonMht;
        }

        public int hiddenDirs() {
            return hiddenDirs;
        }

        public int emptyDirs() {
            return emptyDirs;
        }

        public int unreadable() {
            return unreadable;
        }

        public int depthLimited() {
            return depthLimited;
        }
    }

    /**
     * 开始一个导入会话（建扫描器 + 计数清零）。
     *
     * <p>配额用 {@link MhtImportPlanner} 的默认值（与迁移前控制器私有常量同源）。</p>
     */
    public Session begin(List<String> normalized, String sourceDesc, boolean fromDrag) {
        return begin(normalized, sourceDesc, fromDrag,
                MhtImportPlanner.DEFAULT_MAX_GROUPS, MhtImportPlanner.DEFAULT_MAX_FILES);
    }

    /**
     * 开始一个导入会话（配额可注入）。
     *
     * <p><b>为什么把配额做成参数</b>：生产路径恒用默认值（见上一个重载），而"每轮配额打满 ⇒
     * quotaHit/hasMore 逐轮传递"这条语义只有在配额可缩小时才能用<b>真实扫描器</b>在单测里复现
     * （否则要造 200 个组的目录树）。注入的值必须与调用方打印的配额数一致 ——
     * 生产调用方（{@link WorkspaceImportCoordinator}）打印的就是 {@link MhtImportPlanner} 的默认常量。</p>
     */
    public Session begin(List<String> normalized, String sourceDesc, boolean fromDrag,
                         int maxGroupsPerRound, int maxFilesPerRound) {
        List<String> addrs = normalized == null ? List.of() : List.copyOf(normalized);
        return new Session(addrs, sourceDesc, fromDrag, MhtImportPlanner.scanner(
                addrs, MhtImportPlanner.DEFAULT_MAX_DEPTH, maxGroupsPerRound, maxFilesPerRound));
    }

    /** 扫描下一轮（由导入后台线程调用；返回后 {@code hasMore()} 表示是否还有剩余工作） */
    public MhtImportPlanner.Plan nextRound(Session session) {
        return session.scanner.nextRound();
    }

    // ==================== 一轮计划的规则换算 ====================

    /**
     * 一个批次换算之后的结论。
     *
     * @param dirPath    来源目录（跳过日志用）
     * @param folderName 建组批次的文件夹名；非建组批次为 {@code null}
     * @param grouped    true = 该批次应建组（成员只入组、不入顶层）；false = 平铺到顶层
     * @param items      本轮要新建的条目（{@code skipped()} 为真时为空列表）
     * @param wasEmpty   应用该批次前"列表可见数为 0" ⇒ 调用方需选中首行
     */
    public record ResolvedBatch(String dirPath, String folderName, boolean grouped,
                                List<PreviewItem> items, boolean wasEmpty) {

        public ResolvedBatch {
            items = List.copyOf(items);
        }

        /** 无新文件 ⇒ 该批次不建组（RISK-1） */
        public boolean skipped() {
            return items.isEmpty();
        }

        private static ResolvedBatch skippedBatch(MhtImportPlanner.Batch batch) {
            boolean grouped = batch instanceof MhtImportPlanner.GroupBatch;
            String folderName = batch instanceof MhtImportPlanner.GroupBatch gb ? gb.folderName() : null;
            return new ResolvedBatch(batch.dirPath(), folderName, grouped, List.of(), false);
        }
    }

    /** 一轮计划换算结果（保持批次顺序） */
    public record RoundOutcome(List<ResolvedBatch> batches) {

        public RoundOutcome {
            batches = List.copyOf(batches);
        }

        /** 要真正落地的批次（有新建条目），顺序与扫描顺序一致 */
        public List<ResolvedBatch> applied() {
            return batches.stream().filter(b -> !b.skipped()).toList();
        }
    }

    /**
     * 把一轮 {@link MhtImportPlanner.Plan} 换算为"要新建哪些条目、哪些批次要建组"。
     *
     * <p><b>同时把扫描器累计计数同步进会话</b>（与原 {@code MainController.applyImportPlan} 首段一致：
     * 即使本轮无批次也要同步，收尾汇总结账用它）。</p>
     *
     * <p><b>为什么要把"可见项快照"作为参数传进来</b>：本类不持有模型，也不该知道"哪些项被移除"。
     * 调用方在<b>本轮开始时</b>取一次快照即可 —— 本轮内后续批次的去重口径已由本方法用
     * {@code seen} 集合增量复现（见类 javadoc 语义第 4 条），因此结果与原实现"每批重新读一次可见项"
     * <b>逐条等价</b>，而不再依赖 FX 线程上的实时读取。</p>
     *
     * @param existingVisiblePaths 列表<b>可见</b>项的绝对路径（<b>不得</b>含已移除项）
     * @param visibleCountAtStart  本轮开始时列表的可见项数量（判定 {@code wasEmpty}）
     */
    public RoundOutcome resolveRound(Session session, MhtImportPlanner.Plan plan,
                                     List<String> existingVisiblePaths, int visibleCountAtStart) {
        syncCounters(session, plan);

        Set<String> seen = new LinkedHashSet<>(existingVisiblePaths == null ? List.of() : existingVisiblePaths);
        List<ResolvedBatch> out = new ArrayList<>();
        boolean produced = false;
        for (MhtImportPlanner.Batch batch : plan.batches()) {
            // 去重：与列表可见项比对（复用 F4）——已移除项仍在数据序中，不得视为"已导入"而整批跳过
            List<File> fresh = IncrementalImport.findNewFiles(batch.files(), seen);
            if (fresh.isEmpty()) {
                out.add(ResolvedBatch.skippedBatch(batch));     // RISK-1 硬约束：无新文件则该批次不建组
                continue;
            }
            List<PreviewItem> items = new ArrayList<>(fresh.size());
            for (File f : fresh) {
                BatchProcessor.MhtFileInfo info = BatchProcessor.toMhtFileInfo(f);
                items.add(new PreviewItem(info.getPath(), info.getName(),
                        info.getModifiedTime(), f.getParent()));
            }
            for (PreviewItem it : items) {
                seen.add(it.path);
            }
            // wasEmpty：原实现是"应用该批次之前 visibleCount() == 0"；本轮内已产出过条目的批次必然不再是 0
            boolean wasEmpty = !produced && visibleCountAtStart == 0;
            produced = true;
            boolean grouped = batch instanceof MhtImportPlanner.GroupBatch;
            String folderName = batch instanceof MhtImportPlanner.GroupBatch gb ? gb.folderName() : null;
            out.add(new ResolvedBatch(batch.dirPath(), folderName, grouped, items, wasEmpty));
        }
        return new RoundOutcome(out);
    }

    private static void syncCounters(Session session, MhtImportPlanner.Plan plan) {
        session.ignoredNonMht = plan.ignoredNonMht();
        session.hiddenDirs = plan.hiddenDirs();
        session.emptyDirs = plan.emptyDirs();
        session.unreadable = plan.unreadable();
        session.depthLimited = plan.depthLimited();
    }

    // ==================== 累计（供 GUI 在模型命令之后调用） ====================

    /**
     * 累计本轮新建的条目。
     *
     * <p><b>为什么累计不放在调用方</b>：撤销记录的载荷是"当时的全量累计"，而配额确认文案也要读它
     * （后台线程）；把累计留在会话里，两个读取点读的是同一份状态，与迁移前读控制器字段等价。</p>
     */
    public void accumulate(Session session, List<PreviewItem> items) {
        if (items != null) {
            session.accumulated.addAll(items);
        }
    }

    /** 累计本轮自动创建的组数（原实现是"本轮建组数 += createdGroups.size()"） */
    public void addCreatedGroups(Session session, int count) {
        session.groupCount += count;
    }

    /** 本次导入累计的条目（只读快照） */
    public List<PreviewItem> accumulated(Session session) {
        return session.accumulated();
    }

    /** 本次导入累计自动创建的组数 */
    public int groupCount(Session session) {
        return session.groupCount();
    }

    // ==================== 组名（纯函数） ====================

    /**
     * 组名计算的中间结果。
     *
     * @param base   sanitize 后（必要时退化为"默认前缀 + 组号"）的原始名
     * @param unique 与既有组名唯一化之后的最终名（{@code log.maincontroller.09} 只在两者不同时打）
     */
    public record GroupName(String base, String unique) {
    }

    /**
     * 组名计算（Q11/R6 之后建组路径还会复用，故抽成纯函数）：
     * sanitize（保证"列表显示名 == 输出名"F10/BC-6）→ 空名退化为"默认前缀 + 组号"→ 与既有组名唯一化（F7）。
     *
     * <p><b>为什么默认前缀由调用方传入</b>：它是界面文案（zh {@code 组} / en {@code Group}，键
     * {@code core.groupDefault}），而本类不调 {@code I18n}。调用方传
     * {@code I18n.get("core.groupDefault")} 即可，规则本身与本类一致。</p>
     *
     * @param existingGroupNames 既有组名集合（唯一来源是 {@code WorkspaceModel.groupNames()}）
     */
    public GroupName resolveGroupName(String folderName, int groupNo, String defaultPrefix,
                                      Collection<String> existingGroupNames) {
        String base = SanitizeUtils.sanitize(folderName);
        if (base.isEmpty()) {
            base = defaultPrefix + groupNo;
        }
        String unique = GroupStructure.uniqueGroupName(base,
                existingGroupNames == null ? List.of() : existingGroupNames);
        return new GroupName(base, unique);
    }
}
package com.mhtextractor.app;

import com.mhtextractor.model.GroupItem;

import java.util.ArrayList;
import java.util.List;
import java.util.function.Predicate;

/**
 * 拖拽落点解析与执行（6.6 拖拽规则，阶段 7）：
 * 把（被拖对象, 目标行, 落点分区）解析为数据序操作，并负责执行、
 * no-op 检测与"拖拽致空组自动销毁"（R4，与移除致空组一致）。
 *
 * <p>落点分区约定：组条目行三区——TOP（组前空隙）/ INTO（整行：入组末尾或两组合并）/ BOTTOM（组后空隙）；
 * 项目行（顶层或组内成员）两区——TOP（行前）/ BOTTOM（行后）。折叠组只有组条目一行，
 * 项目拖到其 INTO = 入组末尾，其上下空隙仍为顶层落点，逻辑与展开状态自洽。</p>
 *
 * <p>本类不感知 GUI 状态，全部为纯函数（apply 直接修改传入的数据序列表），
 * 供 MainController 与单元测试共用。数据序约定：顶层混合列表（项目 | GroupItem），
 * 组内成员存于 GroupItem.members。</p>
 */
@SuppressWarnings({"unchecked", "rawtypes"})
public final class DropResolver {

    private DropResolver() {
    }

    /** 落点分区：TOP = 行上边缘空隙；INTO = 组行整行（入组/合并语义）；BOTTOM = 行下边缘空隙 */
    public enum Zone { TOP, INTO, BOTTOM }

    /**
     * 由鼠标在行内的相对位置算出落点分区（步骤 3 从 {@code MainController.dropZone} 外迁）。
     *
     * <p><b>为什么外迁</b>：这是**纯几何**判定，不依赖任何 UI 框架，却在控制器里是私有方法 ——
     * 单元格类要调用它就必须放宽可见性（即增加"测试支撑暴露面"）。外迁后既不必放宽，
     * 也首次获得直接单测。</p>
     *
     * <p>规则：组行分三区（上下边缘 = 行间空隙，中间带 = 整行入组/合并）；项目行分两区（上/下）。</p>
     *
     * @param row       该行的数据对象（{@code GroupItem} 走三区，其余走两区）
     * @param y         鼠标相对行顶部的 y
     * @param height    行高
     * @param edgeRatio 组行上下边缘带占行高的比例（原 {@code GROUP_ROW_EDGE_ZONE = 0.25}）
     */
    public static Zone zoneFor(Object row, double y, double height, double edgeRatio) {
        if (row instanceof GroupItem<?>) {
            if (y < height * edgeRatio) {
                return Zone.TOP;
            }
            if (y < height * (1 - edgeRatio)) {
                return Zone.INTO;
            }
            return Zone.BOTTOM;
        }
        return y < height / 2 ? Zone.TOP : Zone.BOTTOM;
    }

    /** 一次拖放对应的数据序操作 */
    public sealed interface Operation {
        /** 被拖对象（项目或组条目） */
        Object dragSource();
    }

    /** 项目移动到顶层指定位置（出组到顶层 / 顶层重排） */
    public record InsertTop(Object item, int index) implements Operation {
        @Override
        public Object dragSource() {
            return item;
        }
    }

    /** 项目入组（组内指定落点；memberIndex == 组内成员数即入组末尾） */
    public record InsertInto(Object item, GroupItem<?> group, int memberIndex) implements Operation {
        @Override
        public Object dragSource() {
            return item;
        }
    }

    /** 组条目移动到顶层指定位置（整组移动，成员跟随，仅改变组间顺序） */
    public record MoveGroup(GroupItem<?> group, int index) implements Operation {
        @Override
        public Object dragSource() {
            return group;
        }
    }

    /** 两组合并：dragged 组成员按原顺序插入 target 组 memberIndex，dragged 组销毁（组参数丢弃） */
    public record MergeInto(GroupItem<?> dragged, GroupItem<?> target, int memberIndex) implements Operation {
        @Override
        public Object dragSource() {
            return dragged;
        }
    }

    /**
     * 落点解析：把（被拖对象, 目标行, 分区）解析为数据序操作。
     * 非法组合（拖到自身、组拖到自身组成员行/自身组行、目标不在数据序中等）返回 null。
     * 索引均以解析时刻的数据序为准，apply 执行时自行修正移除偏移。
     */
    public static Operation resolve(List<?> topLevel, Object dragged, Object target, Zone zone) {
        if (dragged == null || target == null || zone == null || dragged == target) {
            return null;
        }
        if (dragged instanceof GroupItem dg) {
            return resolveGroupDrag(topLevel, dg, target, zone);
        }
        return resolveItemDrag(topLevel, dragged, target, zone);
    }

    private static Operation resolveItemDrag(List<?> topLevel, Object item, Object target, Zone zone) {
        if (target instanceof GroupItem tg) {
            int ti = topLevel.indexOf(tg);
            if (ti < 0) {
                return null;
            }
            return switch (zone) {
                case TOP -> new InsertTop(item, ti);
                case INTO -> new InsertInto(item, tg, tg.getMembers().size());
                case BOTTOM -> new InsertTop(item, ti + 1);
            };
        }
        GroupItem parent = findGroupOf(topLevel, target);
        if (parent != null) {
            int mi = parent.getMembers().indexOf(target);
            if (mi < 0) {
                return null;
            }
            return zone == Zone.TOP
                    ? new InsertInto(item, parent, mi)
                    : new InsertInto(item, parent, mi + 1);
        }
        int ti = topLevel.indexOf(target);
        if (ti < 0) {
            return null;
        }
        return zone == Zone.TOP ? new InsertTop(item, ti) : new InsertTop(item, ti + 1);
    }

    private static Operation resolveGroupDrag(List<?> topLevel, GroupItem dg, Object target, Zone zone) {
        if (target instanceof GroupItem tg) {
            if (dg == tg) {
                return null;
            }
            int ti = topLevel.indexOf(tg);
            if (ti < 0) {
                return null;
            }
            return switch (zone) {
                case TOP -> new MoveGroup(dg, ti);
                case INTO -> new MergeInto(dg, tg, tg.getMembers().size());
                case BOTTOM -> new MoveGroup(dg, ti + 1);
            };
        }
        GroupItem parent = findGroupOf(topLevel, target);
        if (parent == dg) {
            // 拖到自己的成员行：无意义
            return null;
        }
        if (parent != null) {
            int mi = parent.getMembers().indexOf(target);
            if (mi < 0) {
                return null;
            }
            return zone == Zone.TOP
                    ? new MergeInto(dg, parent, mi)
                    : new MergeInto(dg, parent, mi + 1);
        }
        int ti = topLevel.indexOf(target);
        if (ti < 0) {
            return null;
        }
        return zone == Zone.TOP ? new MoveGroup(dg, ti) : new MoveGroup(dg, ti + 1);
    }

    /**
     * 执行落点操作：直接修改数据序；结构未变化（原位 no-op）或前置条件不满足时
     * 返回 false 且不修改。removed 谓词用于空组销毁判定（全部成员满足即销毁）。
     */
    public static boolean apply(List<Object> topLevel, Operation op, Predicate<Object> removed) {
        if (op instanceof InsertTop it) {
            return applyInsertTop(topLevel, it, removed);
        }
        if (op instanceof InsertInto ii) {
            return applyInsertInto(topLevel, ii, removed);
        }
        if (op instanceof MoveGroup mg) {
            return applyMoveGroup(topLevel, mg);
        }
        if (op instanceof MergeInto mi) {
            return applyMerge(topLevel, mi);
        }
        return false;
    }

    private static boolean applyInsertTop(List<Object> topLevel, InsertTop op, Predicate<Object> removed) {
        Object item = op.item();
        int ci = topLevel.indexOf(item);
        GroupItem source = null;
        if (ci < 0) {
            source = findGroupOf(topLevel, item);
            if (source == null || !source.getMembers().contains(item)) {
                return false;
            }
        } else if (op.index() == ci || op.index() == ci + 1) {
            return false; // 顶层原位（插入自身前/后等价于不动）
        }
        int d = op.index();
        if (ci >= 0) {
            topLevel.remove(ci);
            if (ci < d) {
                d--;
            }
        } else {
            source.getMembers().remove(item);
            if (source.getMembers().stream().allMatch(removed)) {
                // 拖拽致原组为空 → 原组自动销毁（R4）
                int gIdx = topLevel.indexOf(source);
                topLevel.remove(gIdx);
                if (gIdx < d) {
                    d--;
                }
            }
        }
        topLevel.add(Math.max(0, Math.min(d, topLevel.size())), item);
        return true;
    }

    private static boolean applyInsertInto(List<Object> topLevel, InsertInto op, Predicate<Object> removed) {
        Object item = op.item();
        GroupItem target = op.group();
        if (!topLevel.contains(target)) {
            return false;
        }
        int d = Math.max(0, Math.min(op.memberIndex(), target.getMembers().size()));
        int ci = topLevel.indexOf(item);
        if (ci < 0) {
            GroupItem cur = findGroupOf(topLevel, item);
            if (cur == null || !cur.getMembers().contains(item)) {
                return false;
            }
            if (cur == target) {
                // 同组内排序：原位判定（插入自身前/后等价于不动）
                int mi = target.getMembers().indexOf(item);
                if (d == mi || d == mi + 1) {
                    return false;
                }
                target.getMembers().remove(mi);
                if (d > mi) {
                    d--;
                }
            } else {
                cur.getMembers().remove(item);
                if (cur.getMembers().stream().allMatch(removed)) {
                    topLevel.remove(cur);
                }
            }
        } else {
            topLevel.remove(ci);
        }
        target.getMembers().add(Math.max(0, Math.min(d, target.getMembers().size())), item);
        return true;
    }

    private static boolean applyMoveGroup(List<Object> topLevel, MoveGroup op) {
        GroupItem g = op.group();
        int ci = topLevel.indexOf(g);
        if (ci < 0) {
            return false;
        }
        if (op.index() == ci || op.index() == ci + 1) {
            return false; // 原位
        }
        topLevel.remove(ci);
        int d = op.index();
        if (ci < d) {
            d--;
        }
        topLevel.add(Math.max(0, Math.min(d, topLevel.size())), g);
        return true;
    }

    private static boolean applyMerge(List<Object> topLevel, MergeInto op) {
        GroupItem dragged = op.dragged();
        GroupItem target = op.target();
        if (dragged == target) {
            return false;
        }
        int gi = topLevel.indexOf(dragged);
        if (gi < 0 || !topLevel.contains(target)) {
            return false;
        }
        List<Object> members = new ArrayList<>(dragged.getMembers());
        dragged.getMembers().clear();
        topLevel.remove(gi);
        target.getMembers().addAll(
                Math.max(0, Math.min(op.memberIndex(), target.getMembers().size())), members);
        return true;
    }

    /** 顶层列表中查找包含指定成员的组（项目不在顶层时） */
    private static GroupItem findGroupOf(List<?> topLevel, Object member) {
        for (Object o : topLevel) {
            if (o instanceof GroupItem g && g.getMembers().contains(member)) {
                return g;
            }
        }
        return null;
    }
}
package com.mhtextractor.app;

import com.mhtextractor.model.AppConfig;
import com.mhtextractor.model.GroupItem;
import com.mhtextractor.model.PreviewItem;
import com.mhtextractor.model.FingerprintEncoder;
import com.mhtextractor.model.ParamScope;

import java.util.ArrayList;
import java.util.List;

/**
 * 生效参数服务（R8-①）：把「当前模式下某目标的生效参数是什么」「一组目标的生效参数是否统一 /
 * 组内是否混合」「目标是否存在独立参数」这三件事收敛为<b>全仓库唯一实现点</b>。
 *
 * <p><b>本类零 JavaFX、零第三方依赖、不调 {@code I18n.get}</b>：它只读参数缓存与模型字段，
 * 不产用户文案（{@code app} 层由 {@code ArchitectureTest} 强制）。</p>
 *
 * <h2>为什么是无状态 + 显式 {@link Context}（而不是直接持有 GUI 控件）</h2>
 * <p>两个全局参数缓存（{@code textParamsCache} / {@code imageParamsCache}）在 GUI 侧是<b>可变字段</b>
 * （参数确认 / 应用到全局 / 撤销都会整体替换它们，见 {@code MainController}）。若让本服务持有
 * 这两个引用，就必须处理"换模式、参数被替换后服务读到陈旧值"的问题，且服务会被钉在 GUI 生命周期上。</p>
 * <p>因此本服务<b>不持有任何可变状态</b>：模式与两个全局缓存由调用方每次经 {@link Context} 传入
 * （本质是两个缓存的<b>快照</b> + 一个模式位）。这样服务是纯函数式的、可由测试直接驱动，
 * 而 GUI 侧的"从控件取当前值"这件事收敛到 {@code MainController.effectiveContext()} 一处。</p>
 *
 * <h2>参数解析必须经 {@link ParamScope}（不得绕过、不得复制）</h2>
 * <p>图片模式的生效参数解析必须且只能经 {@link ParamScope#effectiveImageParams} —— 预览落盘与提取
 * （{@code OutputUnitPlanner.resolve}）解析出同一套参数是缓存复用（P10）的前提。本类不复制该逻辑，
 * 只做「按目标类型取出三个候选值 → 交给 {@code ParamScope}」的适配。</p>
 *
 * <h2>值语义口径（"是否统一"怎么比）</h2>
 * <p>{@link AppConfig} 是 Lombok {@code @Data} 可变对象，其 javadoc 明确禁止用 {@code equals} 当
 * 判定键（值会随外部修改而变化）。故本类<b>不调用 {@code equals}</b>，而是把每个配置渲染成
 * <b>字段级内容签名</b>（固定字段顺序 + 长度前缀编码，见 {@link #signatureOf}），再比签名是否相同。
 * 这与 {@code AppConfig.imageExtractionFingerprint()} 是同一套"固定顺序 + 长度前缀"编码风格，
 * 但<b>覆盖范围不同且更宽</b>：</p>
 * <ul>
 *   <li>{@code imageExtractionFingerprint()} 是<b>缓存命中</b>口径，只含影响"提取出哪些图片"的 8 个字段
 *       （P2 明确排除归档与内存模式）；</li>
 *   <li>本类的签名是<b>用户感知</b>口径，覆盖全部用户可设置参数 —— 包括
 *       {@code enableZipPackaging} / {@code enableCbzPackaging} / {@code highSpeedMemoryMode}，
 *       以及文本模式的全部字段。理由：R7 的判据是"多选后存在多个不同生效参数 → 禁用复制/应用"，
 *       用户看到的是"这些设置不一样"，而不是"缓存能不能复用"。</li>
 *   <li>仅排除 4 个<b>非"用户设置的提取参数"</b>的字段：{@code inputFolder} / {@code outputFolder} /
 *       {@code openFolderAfterComplete}（GUI 运行时状态；前两者属 {@code gui-state.json}）与
 *       {@code imageModeEnabled}（{@code AppConfig} javadoc 明写"提取模式属于主窗口 GUI 状态，
 *       运行时由主窗口模式开关写入"—— 它标的是"当前在哪个模式"，而"是否统一"本就只在单一模式内比较）。</li>
 * </ul>
 * <p>签名是 {@code imageExtractionFingerprint()} 的<b>超集</b>：图片模式下签名相同 ⇒ 指纹必然相同
 * （反之不成立），故"统一"判定比"缓存可复用"判定更严格 —— 不会出现"判定为统一却各自缓存不命中"
 * 的不一致方向（该方向才是危险的）。</p>
 */
public final class EffectiveParamsService {

    /** 无生效参数的固定标记（真实签名至少含一个模式位字符，故与任何真实签名都不同） */
    public static final String NO_PARAMS = "<none>";

    /**
     * 一次判定所需的参数解析上下文：当前是否图片模式 + 该模式与另一模式的全局已确认参数缓存
     * （{@code null} = 该模式尚未确认过参数）。
     *
     * <p>不可变快照：调用方在每次判定前重新构造即可（GUI 侧 {@code MainController.effectiveContext()}）。</p>
     */
    public record Context(boolean imageMode, AppConfig textGlobal, AppConfig imageGlobal) {
    }

    /**
     * 生效参数（唯一入口）：
     * <ul>
     *   <li>{@link GroupItem} → 只按组解析（组 &gt; 全局）—— 条目级参数与组目标无关；</li>
     *   <li>{@link PreviewItem} → 三层覆盖：{@code parentGroup} 的组参数 &gt; 条目级参数 &gt; 全局；</li>
     *   <li>null / 其他类型 → {@code null}（无生效参数）。</li>
     * </ul>
     *
     * <p>图片模式经 {@link ParamScope#effectiveImageParams}、文本模式经
     * {@link ParamScope#effectiveParams} —— 与迁移前 {@code MainController.effectiveForObject}
     * 的解析路径<b>逐语义等价</b>（同一个 {@code ParamScope} 分支，不再保留第二份）。</p>
     */
    public AppConfig effectiveFor(Object target, Context ctx) {
        GroupItem<?> parent = null;
        AppConfig itemText = null;
        AppConfig itemImage = null;
        if (target instanceof PreviewItem it) {
            parent = it.parentGroup;
            itemText = it.textItemParams;
            itemImage = it.imageItemParams;
        } else if (target instanceof GroupItem<?> g) {
            parent = g;
        }
        return ctx.imageMode()
                ? ParamScope.effectiveImageParams(parent, itemImage, ctx.imageGlobal())
                : ParamScope.effectiveParams(parent, itemText, itemImage, false,
                        ctx.textGlobal(), ctx.imageGlobal());
    }

    /**
     * 生效参数的来源状态（{@link ParamScope.Status}）：{@code GROUP} = 存在独立参数
     * （组参数或条目级参数），{@code GLOBAL} = 生效参数就是全局参数，{@code NONE} = 无生效参数。
     *
     * <p>这是 {@link #hasIndependentParams} 的原始形态，供视图层需要三态（而不仅二态）时使用。</p>
     */
    public ParamScope.Status effectiveSourceOf(Object target, Context ctx) {
        GroupItem<?> parent = target instanceof PreviewItem it ? it.parentGroup
                : (target instanceof GroupItem<?> g ? g : null);
        AppConfig itemText = target instanceof PreviewItem it ? it.textItemParams : null;
        AppConfig itemImage = target instanceof PreviewItem it ? it.imageItemParams : null;
        return ParamScope.backgroundStatus(parent, itemText, itemImage, ctx.imageMode(),
                ctx.textGlobal(), ctx.imageGlobal());
    }

    /**
     * 目标是否存在<b>独立参数</b>（组参数或条目级参数）—— 即拍板语义"仅此状态『应用到全局』可用"。
     *
     * <p>等价于 {@code effectiveSourceOf(target, ctx) == ParamScope.Status.GROUP}；单留一个实现点
     * （本方法委托 {@link #effectiveSourceOf}），故视图层的"清除参数"/"应用到全局"启用判定与
     * 背景色三态判定<b>共用同一份来源判定</b>，不会再各自演化。</p>
     */
    public boolean hasIndependentParams(Object target, Context ctx) {
        return effectiveSourceOf(target, ctx) == ParamScope.Status.GROUP;
    }

    /**
     * 一组目标的生效参数是否<b>混合</b>（存在多种取值）。
     *
     * <p><b>判定口径（本步明确决定）：{@code null}（无生效参数）算作一种独立取值</b> ——
     * {@code [A, null]} 视为混合。理由：用户在多选列表里看到的确实是"不统一"（一部分条目有参数、
     * 一部分没有），而 R7 的动作是"存在多个不同生效参数 → 禁用复制/应用参数"。若把 {@code null}
     * 忽略，则"一半有参数一半没有"会被判为统一，进而允许把参数复制到无参数条目上 —— 与"复制"的
     * 用户预期相反。</p>
     *
     * <p>边界：<b>空列表与单元素列表均为"不混合"</b>（0 或 1 种取值）。</p>
     */
    public boolean hasMixedEffectiveParams(List<?> targets, Context ctx) {
        if (targets == null || targets.size() < 2) {
            return false;
        }
        // 用有序列存已见签名（选择集规模是"同组/同选择集"，元素极少）：
        // 必须能区分 null 与"某套参数"，故 NO_PARAMS 作为一个独立取值参与去重。
        List<String> seen = new ArrayList<>();
        for (Object target : targets) {
            String sig = signatureOf(effectiveFor(target, ctx));
            if (!seen.contains(sig)) {
                seen.add(sig);
                if (seen.size() > 1) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * 一组目标的生效参数是否<b>统一</b>（{@code !hasMixedEffectiveParams}，只此一个实现点）。
     *
     * <p>边界（与 {@link #hasMixedEffectiveParams} 一致）：空列表与单元素列表均为统一。</p>
     */
    public boolean isUniform(List<?> targets, Context ctx) {
        return !hasMixedEffectiveParams(targets, ctx);
    }

    /** 任一目标存在生效参数（非 null）。空列表 → {@code false}。 */
    public boolean anyHasEffectiveParams(List<?> targets, Context ctx) {
        if (targets == null) {
            return false;
        }
        for (Object target : targets) {
            if (effectiveFor(target, ctx) != null) {
                return true;
            }
        }
        return false;
    }

    /** 全部存在生效参数的目标（保持输入顺序）；供"参数目标信息栏"等展示用途。 */
    public List<Object> targetsWithEffectiveParams(List<?> targets, Context ctx) {
        List<Object> out = new ArrayList<>();
        if (targets != null) {
            for (Object target : targets) {
                if (effectiveFor(target, ctx) != null) {
                    out.add(target);
                }
            }
        }
        return out;
    }

    // ==================== 值语义：字段级内容签名 ====================

    /**
     * 配置的字段级内容签名（{@code null} → 固定标记 {@link #NO_PARAMS}）。
     *
     * <p>固定字段顺序 + 字符串长度前缀编码，不依赖 Map/Set 迭代顺序、不依赖 Lombok 生成顺序，
     * 且<b>不用 {@code equals}/{@code toString}/反射</b> —— 新增字段时签名会变（这正是我们要的：
     * 新参数一旦影响行为就必须参与"是否统一"判定），而不是静默沿用旧判定。
     * {@code AppConfigTest} 有一条"字段守护"用例会提醒同步本方法。</p>
     */
    public static String signatureOf(AppConfig c) {
        if (c == null) {
            return NO_PARAMS;
        }
        StringBuilder sb = new StringBuilder(256);
        // 通用
        sb.append(c.isSeparateFiles() ? '1' : '0');
        // 文本提取
        sb.append(c.isEnableContentLimit() ? '1' : '0');
        FingerprintEncoder.lengthPrefixed(sb, c.getStartMarker());
        FingerprintEncoder.lengthPrefixed(sb, c.getEndMarker());
        sb.append(c.isUseRegex() ? '1' : '0');
        sb.append(c.isEnableTemplate() ? '1' : '0');
        FingerprintEncoder.lengthPrefixed(sb, c.getStartTemplate());
        FingerprintEncoder.lengthPrefixed(sb, c.getEndTemplate());
        sb.append(c.isAddChapterNumber() ? '1' : '0');
        sb.append(c.isAutoFixEncoding() ? '1' : '0');
        sb.append(c.isEnableTitleExtraction() ? '1' : '0');
        FingerprintEncoder.lengthPrefixed(sb, c.getTitleStartMarker());
        FingerprintEncoder.lengthPrefixed(sb, c.getTitleEndMarker());
        sb.append(c.isTitleUseRegex() ? '1' : '0');
        // 图片提取
        sb.append(c.isEnableNameExtraction() ? '1' : '0');
        FingerprintEncoder.lengthPrefixed(sb, c.getImageNameStartMarker());
        FingerprintEncoder.lengthPrefixed(sb, c.getImageNameEndMarker());
        sb.append(c.isEnableRegionExtraction() ? '1' : '0');
        FingerprintEncoder.lengthPrefixed(sb, c.getImageRegionStartMarker());
        FingerprintEncoder.lengthPrefixed(sb, c.getImageRegionEndMarker());
        sb.append(c.isEnableBatchRenaming() ? '1' : '0');
        sb.append(c.isEnableZipPackaging() ? '1' : '0');
        sb.append(c.isEnableCbzPackaging() ? '1' : '0');
        sb.append(c.isSingleOutputMode() ? '1' : '0');
        // 处理模式
        sb.append(c.isHighSpeedMemoryMode() ? '1' : '0');
        // 兼容旧版废弃字段（保留反序列化兼容；仍参与判定，避免"设置里看得见却不影响判定"）
        FingerprintEncoder.lengthPrefixed(sb, c.getNameLimitStart());
        FingerprintEncoder.lengthPrefixed(sb, c.getNameLimitEnd());
        FingerprintEncoder.lengthPrefixed(sb, c.getContentLimitStart());
        FingerprintEncoder.lengthPrefixed(sb, c.getContentLimitEnd());
        return sb.toString();
    }

    /**
     * 仅供签名一致性守护测试使用：本签名刻意排除的 AppConfig 字段
     * （纯运行时/GUI 状态，不属于"用户设置的提取参数"）。
     *
     * <p>返回<b>不可变副本</b>，避免测试或调用方改动内部集合。</p>
     */
    public static List<String> runtimeOnlyFields() {
        return List.copyOf(RUNTIME_ONLY_FIELDS);
    }

    private static final List<String> RUNTIME_ONLY_FIELDS =
            List.of("inputFolder", "outputFolder", "imageModeEnabled", "openFolderAfterComplete");
}

package com.mhtextractor.gui;

import com.mhtextractor.app.WorkspaceChange;
import com.mhtextractor.uicore.WorkspaceView;
import javafx.application.Platform;
import javafx.collections.FXCollections;
import javafx.collections.ObservableList;
import javafx.scene.control.ListView;

import java.util.AbstractList;
import java.util.List;
import java.util.function.Consumer;

/**
 * 工作区模型的 **JavaFX 投影层**（Q4 / P3）—— 「模型唯一拥有业务数据，JavaFX 列表是它的投影」的落地处。
 *
 * <p><b>它拥有两份投影</b>（都在 FX 线程使用）：</p>
 * <ol>
 *   <li>{@link #displayItems()} —— <b>显示序</b>（{@code ListView} 直接绑定的那张展平表）。
 *       它是本类<b>唯一维护</b>的可变列表：{@link #project()} 用
 *       {@link WorkspaceView#displayOrder()} 一次性 {@code setAll}（第一阶段只做全量投影，
 *       增量 diff 要等"测量证明 setAll 有性能问题"才做 —— 指南明令）；</li>
 *   <li>{@link #dataOrder()} —— <b>数据序只读投影</b>：读直达模型内部存储
 *       （{@link WorkspaceView#topLevelView()}，零拷贝实时视图），任何写操作抛
 *       {@code UnsupportedOperationException}，<b>唯一例外</b>是 {@code clear()} ——
 *       它转发为模型命令 {@link WorkspaceView#clearItems()}（"清场只清列表"的既有语义）。
 *       保留这个入口是为了让 {@code FeatureExercise}（P7 才改造）继续以 {@code mc.items} 驱动演练，
 *       同时不给 GUI 留下任何"绕过模型写数据序"的路。</li>
 * </ol>
 *
 * <p><b>🚩 本步的取舍：订阅变更，但<b>不</b>在每次变更上自动投影（逐条给理由）</b></p>
 * <p>指南对 adapter 的要求是"订阅 {@link WorkspaceChange}，只在 FX 线程应用"，
 * 并<b>同时</b>明令"不要在动画流程中重复发布中间快照"。这两条在本步的代码事实下会互相打架：</p>
 * <ol>
 *   <li><b>拖拽动画的时序会坏</b>：{@code performResolvedDrop} 先改数据序、再由
 *       {@code animateReleaseInsert} <b>先拍旧布局快照</b>、随后才重建显示序并让快照滑到新位置。
 *       若 adapter 在 {@code applyResolvedDrop} 那一刻就 setAll，动画拍到的"旧布局"已是新布局
 *       —— 视觉上就是"没有让位动画"。这正是指南警告的那件事。</li>
 *   <li><b>会重新引入导入路径刻意避免的 O(批次数 × n)</b>：{@code WorkspaceImportCoordinator}
 *       每轮只刷一次列表（RISK-8，不是每批一次）；逐变更自动投影会把这条优化抹掉。</li>
 *   <li><b>选中抖动</b>：{@code setAll} 会重置 {@code ListView} 的选择模型，再按对象钉回。
 *       每次结构命令多一次"清选择 → 重选"，等于把选中监听回调翻倍，属可观察行为变化。</li>
 * </ol>
 * <p>因此本步的实现是：adapter <b>订阅</b>变更（{@link #isStale()} 可查"自上次投影以来模型是否变过"），
 * 而<b>投影时机仍由调用方显式给出</b>（{@link #project()} / {@link #refresh()}），调用点与迁移前的
 * {@code rebuildDisplay()} / {@code refreshAfterListChange()} 一一对应 —— 于是行为逐字保持，
 * 而"谁写显示序"已经收口到本类。P4 把动画整块搬进来时，再打开"变更即投影"（那时不再有中间快照问题）。</p>
 *
 * <p><b>线程约定（FX 线程守卫已落地）</b>：{@link #project()} / {@link #refresh()} /
 * {@link #bindListView(ListView)} 的生产调用点全在 FX 线程（{@code initialize}、命令回调、
 * {@code refreshAfterListChange}）。守卫在<b>投产接线点</b>生效：{@link #bindListView(ListView)}
 * 校验自身在 FX 线程（绑定 ListView 是场景图写操作）并把守卫<b>打开</b>；此后
 * {@link #project()} / {@link #refresh()} 在非 FX 线程调用即抛 {@link IllegalStateException}
 * （消息指明方法名）。未接线（无头投影测试）不守卫 —— 测试不必起 FX toolkit。</p>
 */
public final class WorkspaceFxAdapter {

    /**
     * 选择/焦点宿主：生产是 {@code ListView} 的选择模型，测试可注入桩。
     *
     * <p><b>为什么不让 adapter 直接持有 {@code ListView}</b>：投影一致性测试不该被"必须起 FX toolkit"
     * 绑住（打包机可能没有显示器），而"恢复选中"这条规则本身只依赖"读当前选中 / 写选中"两个操作。</p>
     */
    public interface SelectionHost {

        /** 投影前的选中对象（可为 null） */
        Object selectedItem();

        /** 投影后按对象钉住选中 */
        void select(Object item);

        /** 无宿主：只投影、不恢复选中 */
        SelectionHost NONE = new SelectionHost() {
            @Override
            public Object selectedItem() {
                return null;
            }

            @Override
            public void select(Object item) {
                // 无宿主：不恢复选中
            }
        };
    }

    private final WorkspaceView model;

    /** 显示序（ListView 直接绑定）—— 本类独占维护 */
    private final ObservableList<Object> displayItems = FXCollections.observableArrayList();

    /** 数据序只读投影 —— 见类 javadoc 的第 2 条 */
    private final List<Object> dataOrder;

    /** 订阅句柄（存字段而不是每次 {@code this::onChange}：{@code removeListener} 必须能退掉同一个实例） */
    private final Consumer<WorkspaceChange> listener = this::onChange;

    /** 选择宿主；默认 {@link SelectionHost#NONE} */
    private SelectionHost host = SelectionHost.NONE;

    /** 自上次投影以来模型是否发布过变更（订阅的可观察产物；P4 打开自动投影后用它做合并刷新） */
    private boolean stale = false;
    private long projectedVersion;

    /** bindListView 之后 project()/refresh() 的 FX 线程守卫开关（只有投产接线点置 true；未接线不守卫，无头投影测试不必起 toolkit） */
    private boolean fxThreadGuarded = false;

    /**
     * @param model 被投影的模型（非 null）
     */
    public WorkspaceFxAdapter(WorkspaceView model) {
        this(model, SelectionHost.NONE);
    }

    /**
     * @param model 被投影的模型（非 null）
     * @param host  选择宿主（null 视为 {@link SelectionHost#NONE}）
     */
    public WorkspaceFxAdapter(WorkspaceView model, SelectionHost host) {
        this.model = model;
        this.host = host == null ? SelectionHost.NONE : host;
        // 数据序只读投影：AbstractList 只要求 get/size；add/remove/set 由基类抛 UnsupportedOperationException
        this.dataOrder = new AbstractList<>() {
            @Override
            public Object get(int index) {
                return model.topLevelView().get(index);
            }

            @Override
            public int size() {
                return model.topLevelView().size();
            }

            @Override
            public void clear() {
                model.clearItems();
            }
        };

    }

    /** 被投影的模型 */
    public WorkspaceView model() {
        return model;
    }

    /** 显示序：{@code ListView} 直接绑定它；只由本类的 {@link #project()} / {@link #hideRow(Object)} 维护 */
    public ObservableList<Object> displayItems() {
        return displayItems;
    }

    /** 数据序只读投影（{@code MainController.items} 的来源；写操作抛异常，{@code clear()} 转发为模型命令） */
    public List<Object> dataOrder() {
        return dataOrder;
    }

    /** 自上次投影以来模型是否发布过变更（订阅证据，也是 P4 自动投影的合并依据） */
    public boolean isStale() {
        return projectedVersion != model.version();
    }

    /** 绑定选择宿主（生产：{@code ListView} 的选择模型） */
    public void bindSelection(SelectionHost host) {
        this.host = host == null ? SelectionHost.NONE : host;
    }

    /**
     * 绑定 {@code ListView}：把 {@link #displayItems()} 交给它渲染，并以它的选择模型为选择宿主。
     *
     * <p>调用点是 {@code MainController.initialize()}（FX 线程）。绑定之后
     * "ListView 显示的东西"与"本类的显示序"是<b>同一个列表对象</b>，
     * 因此"ListView 最终显示与模型一致"等价于"displayItems 与 {@code model.displayOrder()} 一致"。</p>
     */
    public void bindListView(ListView<Object> listView) {
        if (!Platform.isFxApplicationThread()) {
            throw new IllegalStateException("WorkspaceFxAdapter.bindListView 必须在 FX 线程调用（绑定 ListView 是场景图写操作）");
        }
        listView.setItems(displayItems);
        bindSelection(new SelectionHost() {
            @Override
            public Object selectedItem() {
                return listView.getSelectionModel().getSelectedItem();
            }

            @Override
            public void select(Object item) {
                listView.getSelectionModel().select(item);
            }
        });
        fxThreadGuarded = true;
    }

    /** 退订（宿主窗口销毁时用；未订阅是 no-op） */
    public void dispose() {
        model.dispose();
    }

    /**
     * <b>全量投影</b>：把显示序一次性对齐到 {@link WorkspaceView#displayOrder()}，
     * <b>不</b>碰选中（对应迁移前的 {@code MainController.rebuildDisplay()} 的那一行 {@code setAll}）。
     *
     * <p>动画路径（提起/松手/展开折叠）用它自己那一套：它们需要"什么时候重建"由动画掌握，
     * 见类 javadoc 的取舍说明。</p>
     */
    public void project() {
        assertFxThread("project");
        displayItems.setAll(model.displayOrder());
        projectedVersion=model.version();
        stale = false;
    }

    /**
     * <b>投影 + 按对象钉住选中</b>：逐字对齐迁移前 {@code refreshAfterListChange} 的头部三行 ——
     *
     * <pre>
     * Object sel = fileListView.getSelectionModel().getSelectedItem();
     * rebuildDisplay();
     * if (sel != null &amp;&amp; displayItems.contains(sel)) fileListView.getSelectionModel().select(sel);
     * </pre>
     *
     * <p>⚠️ <b>不发明新规则</b>：选中对象已不可见时本方法<b>什么都不做</b>（迁移前也是如此）——
     * "选中邻近项"由调用方的具名操作负责（如 {@code selectNearestVisible}），不在这里兜底。</p>
     */
    public void refresh() {
        assertFxThread("refresh");
        Object sel = host.selectedItem();
        project();
        if (sel != null && displayItems.contains(sel)) {
            host.select(sel);
        }
    }

    /**
     * FX 线程守卫：仅当 {@link #bindListView(ListView)}（投产接线点）已打开守卫时生效。
     * 未接线（无头投影测试）不守卫 —— 也让 {@code Platform.isFxApplicationThread()}（会尝试
     * 初始化 toolkit）绝不在无头路径上被求值。
     */
    private void assertFxThread(String method) {
        if (fxThreadGuarded && !Platform.isFxApplicationThread()) {
            throw new IllegalStateException("WorkspaceFxAdapter." + method + " 必须在 FX 线程调用（已 bindListView）");
        }
    }

    /**
     * 从显示序里<b>瞬时摘除</b>一行：提起动画用（拖动中的行由覆盖层快照顶替，真实行先移出列表）。
     *
     * <p>这是"显示序写入收口到 adapter"后留下的唯一一个动画专用口子；P4 把动画整块搬进来时它应被吸收进
     * 动画实现，而不是继续作为公开入口存在。</p>
     */
    public void hideRow(Object item) {
        displayItems.remove(item);
    }

    /** 订阅回调：只记"脏"，不投影（理由见类 javadoc） */
    private void onChange(WorkspaceChange change) {
        stale = true;
    }
}
