    /** 需要盘符根目录确认的地址（toPath().getParent() == null，对 "D:\" 与 UNC 成立） */
    public static List<String> findDriveRoots(List<String> addresses) {
        if (addresses == null) {
            return List.of();
        }
        List<String> out = new ArrayList<>();
        for (String a : addresses) {
            if (a == null || a.isBlank()) {
                continue;
            }
            try {
                Path p = Path.of(a);
                if (p.getParent() == null) {
                    out.add(a);
                }
            } catch (RuntimeException e) {
                // 非法路径格式：不视为盘符根目录
            }
        }
        return out;
    }

